const TRANSFORMS = [
    function(point) { return { x: point.x, y: point.y }; },
    function(point) { return { x: -point.y, y: point.x }; },
    function(point) { return { x: -point.x, y: -point.y }; },
    function(point) { return { x: point.y, y: -point.x }; },
    function(point) { return { x: -point.x, y: point.y }; },
    function(point) { return { x: point.x, y: -point.y }; },
    function(point) { return { x: point.y, y: point.x }; },
    function(point) { return { x: -point.y, y: -point.x }; }
];

