};

normalizeCoreTemplate.source:
var normalizeCoreTemplate = function(template, storagePos) {
    let normalized = {};
    for(let structureType in template) {
        normalized[structureType] = template[structureType].map((pos) => ({
            x: pos.x - storagePos.x,
            y: pos.y - storagePos.y
        }));
    }
    return normalized;
};

