processBuildFlags.source:
var processBuildFlags = function() {
    var buildFlags = _(Game.flags).filter(function (flag) {
        return flag.name.indexOf('Build') >= 0
    }).value();

    while (buildFlags.length > 0) {

        var buildFlag = buildFlags.pop();

		let buildInfo = buildFlag.name.split(':');
		let strType = buildInfo[1];
		let roomName = buildInfo[2];
		let rclLevel = 1;
		if(buildInfo.length > 3) rclLevel = buildInfo[3];

		let supportedTypes = [
				STRUCTURE_SPAWN,
				STRUCTURE_EXTENSION,
				STRUCTURE_ROAD,
				STRUCTURE_WALL,
				STRUCTURE_RAMPART,
				STRUCTURE_LINK,
				STRUCTURE_STORAGE,
				STRUCTURE_TOWER,
				STRUCTURE_OBSERVER,
				STRUCTURE_POWER_SPAWN,
				STRUCTURE_EXTRACTOR,
				STRUCTURE_LAB,
				STRUCTURE_TERMINAL,
				STRUCTURE_CONTAINER,
				STRUCTURE_NUKER,
				STRUCTURE_FACTORY
		];

		for(let type of supportedTypes) {
			if(strType === type) {
				if(!Memory.build) Memory.build = {};
				if(!Memory.build[buildFlag.pos.roomName]) Memory.build[buildFlag.pos.roomName] = {};
				if(!Memory.build[buildFlag.pos.roomName][type]) Memory.build[buildFlag.pos.roomName][type] = [];

				let maxAllowed = CONTROLLER_STRUCTURES[type][8];

                if(Game.rooms[buildFlag.pos.roomName] != undefined) {
				    let existingStructures = Game.rooms[buildFlag.pos.roomName].find(FIND_MY_STRUCTURES, {filter: {structureType: type}});

    				if(existingStructures.length + 1 > maxAllowed) {
    								console.log('Could not process build flag ' + buildFlag.name + ' as there are already ' + maxAllowed + ' ' + type + ' structures');
    								break;
    				}
                }

				// Add this info to memory.
				Memory.build[buildFlag.pos.roomName][type].push({
								t: type,
								pos: buildFlag.pos,
								level: rclLevel,
								source: 'flag',
								priority: -1000,
								key: type + ':' + buildFlag.pos.x + ':' + buildFlag.pos.y
				});
				buildFlag.remove();
			}
		}
	}
};

getRoomSpawnTasks.source:
var getRoomSpawnTasks = function(roomName) {
    var spawnTasks = [];

    for(let spawnTask of Memory.spawnTasks) {
        if(spawnTask.roomName && spawnTask.roomName.constructor === Array) {
            for(let rm of spawnTask.roomName) {
                if(rm == roomName) {
                    spawnTasks.push(spawnTask);
                    break;
                }
            }
        } else if(spawnTask.roomName == roomName) {
            spawnTasks.push(spawnTask);
        }
    }

    return spawnTasks;
};

