var processSpawnTasks = function(roomName) {
    var room = Game.rooms[roomName];
    //var roomTasks = _(Memory.spawnTasks).filter((o) => o.roomName == roomName);
    //var roomTasks = _.filterWithCache('Memory.spawnTasks.'+roomName, Memory.spawnTasks, {roomName: roomName});
    var roomTasks = getRoomSpawnTasks(roomName);
    roomTasks = roomTasks.sort((a,b) => b.priority - a.priority);
    if(roomTasks.length == 0) {
        util.clearSpawnStarvation(roomName);
        return;
    }

    var task = {};
    var spawning = false;
    while(!spawning && task) {
        task = roomTasks.pop();
        if(task === undefined) {
            util.clearSpawnStarvation(roomName);
            return;
        }
        if(room.controller.level < 6) {
            if(task.role == 'truck' || task.role == 'trailor') continue;
            if(task.role == 'miner') {
                if (!task.memory.assignedNode || task.memory.assignedNode.roomName == roomName) {

                } else if(util.isKeeperRoom(task.memory.assignedNode.roomName)) continue;
            }

            if(room.controller.level < 3) {
                if(task.role == 'reserver') continue;
            }
        }
        if(room.storage && room.storage.store[RESOURCE_ENERGY] < 50000) {
            if((task.role == 'miner') && util.isKeeperRoom(task.memory.assignedNode.roomName)) continue;
        }
        //if(roomName == 'E17S29') console.log(JSON.stringify(task));
        var spawn = getAvailableSpawn(room);
        //var body = getBody();
        if(spawn != undefined) {
            var budget = room.energyCapacityAvailable;
            if(task.memory != undefined && task.memory.budget != undefined) {
                budget = task.memory.budget;
                task.memory.homeRoom = roomName;
            }
            var body = getBody(task.role, room, task.boostLevel, budget, task.memory, task.memory === undefined ? false : task.memory.isKeeperRoom);
            var memory = {
                role: task.role,
                homeRoom: roomName
            };
            memory = applyBoosts(task, memory);
            memory = applyTaskMemory(task, memory);
    /*
             if(roomName == 'W3N65') console.log('budget: '+budget);
             if(roomName == 'W3N65') console.log('Body: '+JSON.stringify(body));
             if(roomName == 'W3N65') console.log('memory: '+JSON.stringify(memory));
             //*/
            var result = spawn.canCreateCreep(body);
            //if(roomName == 'E17S29') console.log('result '+result);
            if(result == OK) {
                spawning = true;
                var creepName = spawn.createCreep(body, task.role+task.id, memory);
                util.updateCreepCache(creepName, task.role, memory.homeRoom, body);
                util.recordSpawnUsage(roomName, spawn.name, body.length);

                if(task.role == 'scout') {
                    let scouting = util.getRoomScoutingMemory(roomName);
                    scouting.lastScoutCreated = Game.time;
                }

                if (task.role == 'defender') {
                    Memory.manager.defense[roomName].defenders.push(creepName);
                }

                console.log(`[${roomName}] SPAWN TASK: ${getRoleText(task.role, creepName)}`);
                _.remove(Memory.spawnTasks, (o) => o.id == task.id);

                wakeUpDistributors(roomName);

            } else if(result == ERR_NOT_ENOUGH_ENERGY) {
                util.recordSpawnStarvation(roomName, spawn.name);
            } else {
                util.clearSpawnStarvation(roomName, spawn.name);
                //console.log('Result: '+result);
                //if(roomName == 'E45S28') console.log(`Couldn't spawn ${task.role} with body ${JSON.stringify(body)} with room energy available at ${room.energyAvailable}`);
            }
            return;
        }

    }

    util.clearSpawnStarvation(roomName);

};

