var getBody = function(role, room, boostLevel = 0, budget = -1, memory, isKeeperRoom) {
    var body = [];
    var budget = budget > 0 ? budget : room.energyCapacityAvailable;
    boostLevel++;

    switch(role) {
        case 'scavenger':
            body = buildRoadScavengerBody(budget);
            break;
        case 'depositHarvester':
            for(let i = 0; i < 2; i++) body.push(MOVE);
            for(let i = 0; i < 1; i++) body.push(CARRY);
            for(let i = 0; i < 1; i++) body.push(WORK);
            break;
        case 'depositCourier':
            for(let i = 0; i < 1; i++) body.push(MOVE);
            for(let i = 0; i < 1; i++) body.push(CARRY);
            break;
        case 'scout':
            body = [MOVE];
            break;
        case 'miner':
            if(memory != undefined && memory.isMineral) {
                if(room.controller.level == 8) {
                    for(let i = 0; i < 17; i++) body.push(MOVE);
                    for(let i = 0; i < 2; i++) body.push(CARRY);
                    for(let i = 0; i < 31; i++) body.push(WORK);
                } else {
                    body = getBody('mineralMiner', room, boostLevel, budget, memory, isKeeperRoom);
                }
                break;
            }
            if(isKeeperRoom) {
                body = [WORK, WORK, WORK, WORK, WORK, WORK, WORK, WORK, WORK, CARRY, CARRY, MOVE, MOVE, MOVE, MOVE, MOVE, MOVE];
                break;
            }
            // var miners = _.filterWithCache('Game.creeps.miners', Game.creeps, {memory: {role:'miner'}});
            // miners = _.filter(miners, {memory: {assignedNode:{roomName: room.name}}});
            if(!Memory.manager.creeps.miner) Memory.manager.creeps.miner = {};
            if(!Memory.manager.creeps.miner[room.name]) Memory.manager.creeps.miner[room.name] = {};
            if(!Memory.manager.creeps.miner[room.name].units) Memory.manager.creeps.miner[room.name].units = {};
            var miners = Object.keys(Memory.manager.creeps.miner[room.name].units);
            //var miners = util.getCreeps('miner', room.name);
            // var distributors = _.filterWithCache('Game.creeps.distributors', Game.creeps, {memory: {role:'distributor'}});
            // distributors = _.filter(distributors, {memory: {assignedNode:{roomName: room.name}}});
            if (!Memory.manager.creeps.distributor) Memory.manager.creeps.distributor = {};
            if (!Memory.manager.creeps.distributor[room.name]) Memory.manager.creeps.distributor[room.name] = {};
            if (!Memory.manager.creeps.distributor[room.name].units) Memory.manager.creeps.distributor[room.name].units = {};
            var distributors = Object.keys(Memory.manager.creeps.distributor[room.name].units);
// if(room.name == 'W5N53') console.log('Miners: '+miners.length);
            if(miners.length == 0) {
                if(room.storage && room.storage[RESOURCE_ENERGY] > 5000) {

                } else {
                    budget = room.energyAvailable;
                }
            }

            if(budget >= 900) {
                body = [WORK, WORK, WORK, WORK, WORK, WORK, CARRY, CARRY, MOVE, MOVE, MOVE, MOVE];
            } else if(budget >= 800) {
                body = [WORK, WORK, WORK, WORK, WORK, WORK, CARRY, MOVE, MOVE, MOVE];
            } else if(budget >= 550) {
                body = [WORK, WORK, WORK, WORK, CARRY, MOVE, MOVE];
            } else {
                body = [WORK, WORK, CARRY, MOVE];
            }
            break;
        case 'courier':

            var couriers = [];
            if(!Memory.manager.creeps.courier) Memory.manager.creeps.courier = {};
            if(Memory.manager.creeps.courier[room.name]) {
                if(Memory.manager.creeps.courier[room.name].units) couriers = Object.keys(Memory.manager.creeps.courier[room.name].units);
                if(!couriers) couriers = [];
            }
            var distributors = [];
            if(Memory.manager.creeps.distributor[room.name]) {
                if(Memory.manager.creeps.distributor[room.name].units) distributors = Object.keys(Memory.manager.creeps.distributor[room.name].units);
                if(!distributors) distributors = [];
            }

            // if(room.name == 'W3N65') console.log('couriers: '+JSON.stringify(couriers));
            // if(room.name == 'W3N65') console.log('couriers.length: '+JSON.stringify(couriers.length));

            if(couriers.length == 0) budget = room.energyAvailable;

            if(budget > room.energyCapacityAvailable) budget = room.energyCapacityAvailable;

            if(budget > 50 * 48 + 200)budget = 50 * 48 + 200;

            if(room.storage && room.storage[RESOURCE_ENERGY] > 5000 && distributors.length > 0 && room.energyCapacityAvailable >= 1100 && budget < 1100) budget = 1100;

            if(budget >= 1100 || (room.storage && distributors.length > 0 && room.energyCapacityAvailable >= 1100)) {
                var multiplier = Math.floor((budget - 150) / 150);

                for(let i = 0; i < multiplier * 2; i++) body.push(CARRY);
                body.push(WORK);
