                for(var i = 0; i < multiplier; i++) body.push(MOVE);

            }

            /*
             if(roomLevel >= 4) { // Lets count on there being roads...
             if(room.name != 'W3N55') {
             if (budget > 750) budget = 750;
             } else {
             if(budget > 1200) budget = 1200;
             }
             var multiplier;
             if (couriers.length == 0) {
             multiplier = Math.floor(room.energyAvailable / 150);
             if(multiplier > 6) multiplier = 6;
             } else {
             multiplier = Math.floor(budget / 150);
             }

             for (var i = 0; i < 2*multiplier; i++) body.push(CARRY);
             for (var i = 0; i < multiplier; i++) body.push(MOVE);
             } else {
             var multiplier;
             if (couriers.length == 0) {
             multiplier = Math.floor(room.energyAvailable / 100);
             } else {
             multiplier = Math.floor(budget / 100);
             }

             for (var i = 0; i < multiplier; i++) body.push(CARRY);
             for (var i = 0; i < multiplier; i++) body.push(MOVE);
             }*/
            break;
        case 'upgrader':
            let remoteUpgrader = false;
            if(memory && memory.remoteUpgrader) remoteUpgrader = true;
