                    for (var i = 0; i < 9 + multiplier; i++) body.push(MOVE);
                    for (var i = 0; i < 15 + (2 * multiplier); i++) body.push(WORK);
                    for (var i = 0; i < 3; i++) body.push(CARRY);
                } else {
