                } else if (budget < 750) {
                    body = [WORK, WORK, CARRY, CARRY, MOVE, MOVE, MOVE, MOVE];
                } else if (budget < 1000) {
                    body = [WORK, WORK, WORK, CARRY, CARRY, CARRY, MOVE, MOVE, MOVE, MOVE, MOVE, MOVE];
                } else {
