             body.push(WORK);
             for(var i = 0; i < 2*multiplier; i++) body.push(CARRY);
             for(var i = 0; i < multiplier + 1; i++) body.push(MOVE);//*/

            var multiplier = budget / 150;
            multiplier = Math.floor(multiplier);

            if(multiplier > 15) multiplier = 15;

            for(var i = 0; i < 2*multiplier; i++) body.push(CARRY);
            for(var i = 0; i < multiplier; i++) body.push(MOVE);



            //body = [CARRY, CARRY, CARRY, CARRY, MOVE, MOVE];
