                for (var i = 0; i < 6; i++) body.push(TOUGH);
                for (var i = 0; i < 6; i++) body.push(MOVE);
                for (var i = 0; i < 18; i++) body.push(RANGED_ATTACK);
                // body = getTwoBodyAssaultStructure(budget, boostLevel, RANGED_ATTACK);
            } else if (memory.type == 'melee') {
                body = getTwoBodyAssaultStructure(budget, boostLevel, ATTACK);
            }
            break;
        case 'hunter':
            if(budget >= 700) {
                var multiplier = Math.floor(budget / 700);
                if(memory && memory.remoteDefenseHunterScale !== undefined) {
                    multiplier = Math.min(multiplier, Math.max(1, memory.remoteDefenseHunterScale));
                }
                if(multiplier > 8) multiplier = 8;

                for (var i = 0; i < multiplier * 2; i++) body.push(RANGED_ATTACK);
                for (var i = 0; i < multiplier; i++) body.push(HEAL);
                for (var i = 0; i < multiplier * 3; i++) body.push(MOVE);
            } else if(budget >= 250) {
                body = [RANGED_ATTACK, MOVE, MOVE];
            } else {
                body = [MOVE];
            }
            break;
        case 'upgradeMaster':
            for (var i = 0; i < 1; i++) body.push(MOVE);
            for (var i = 0; i < 18; i++) body.push(CARRY);
            break;
        case 'Z':
            //if (!Memory.harasserEscalation || Memory.harasserEscalation == 0) {
            if(boostLevel && boostLevel > 1) {
                body = [TOUGH, TOUGH, RANGED_ATTACK, RANGED_ATTACK, RANGED_ATTACK, RANGED_ATTACK, HEAL, HEAL, MOVE, MOVE];
            } else {
                var multiplier = (budget - 420) / 200;
                multiplier = Math.floor(multiplier);

                for (var i = 0; i < 2; i++) body.push(TOUGH);
                for (var i = 0; i < multiplier + 3; i++) body.push(MOVE);
                for (var i = 0; i < multiplier; i++) body.push(RANGED_ATTACK);
                for (var i = 0; i < 1; i++) body.push(HEAL);
                //body = [TOUGH, TOUGH, RANGED_ATTACK, MOVE, MOVE, MOVE, MOVE, HEAL];
                body = [RANGED_ATTACK, RANGED_ATTACK, RANGED_ATTACK, MOVE, MOVE, MOVE, MOVE, MOVE, HEAL, HEAL];
            }
            //} else if (Memory.harasserEscalation == 1) {

            break;
        case 'test':
            body = [MOVE];

            break;
    }

    return body;
};
